def match_parens(lst):
    def is_balanced(s1, s2):
        # Check total counts first for efficiency (optional but helpful)
        open_count = sum(1 for c in s1 + s2 if c == '(')
        close_count = len(s1) + len(s2) - open_count
        if open_count != close_count:
            return False

        balance = 0
        # Process first string
        for char in s1:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False

        # Continue with second string
        for char in s2:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False

        return balance == 0

    s1, s2 = lst[0], lst[1]

    # Try both orders
    if is_balanced(s1, s2) or is_balanced(s2, s1):
        return 'Yes'
    else:
        return 'No'

